actions.command:
python3 -c 'from pathlib import Path; import hashlib,json; names=["new-direction/decision-map.md","new-direction/response.md","resume-changed-premise/decision-map.md","resume-changed-premise/response.md","ready-continuation/plan.md","ready-continuation/response.md","loading.json"]; records=[]
for name in names:
 raw=Path(name).read_bytes(); records.append({"path":name,"sha256":hashlib.sha256(raw).hexdigest(),"contents":raw.decode()})
loading=json.loads(Path("loading.json").read_text()); unchanged=[]
for item in loading["inputFixtures"]:
 if item["path"]!="resume-changed-premise/decision-map.md":
  raw=Path(item["path"]).read_bytes(); unchanged.append({"path":item["path"],"matchesOriginal":hashlib.sha256(raw).hexdigest()==item["sha256"]})
resources=[]
for item in loading["loadedInstructions"]+loading["loadedResources"]:
 raw=Path(item["path"]).read_bytes(); resources.append({"path":item["path"],"contentsAndHashMatch":raw.decode()==item["contents"] and hashlib.sha256(raw).hexdigest()==item["sha256"]})
print(json.dumps({"artifacts":records,"unchangedInputs":unchanged,"resources":resources,"readyCaseHasNoDiscoveryMap":not Path("ready-continuation/decision-map.md").exists(),"allFiles":sorted(str(p) for p in Path(".").rglob("*") if p.is_file())},ensure_ascii=False))'
